package zombie.core.properties;
public final class PropertyContainer{public final java.util.Set<zombie.iso.SpriteDetails.IsoFlagType> flags=new java.util.LinkedHashSet<>();public final java.util.Map<String,String> properties=new java.util.LinkedHashMap<>();public boolean has(zombie.iso.SpriteDetails.IsoFlagType f){return flags.contains(f);}public boolean has(String name){return properties.containsKey(name);}public String get(String name){return properties.get(name);}public java.util.ArrayList<zombie.iso.SpriteDetails.IsoFlagType> getFlagsList(){return new java.util.ArrayList<>(flags);}public java.util.ArrayList<String> getPropertyNames(){return new java.util.ArrayList<>(properties.keySet());}}
